style.css:
@-moz-document domain("glitch.com") {
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #fafafa;
    color: #333;
  }

  .illustration-container {
    width: 100%;
    height: 400px;
    background: url('https://cdn.dribbble.com/userupload/2494762/file/still-885dcc1c341d721166019d0c8d51f488.gif?resize=400x0') center no-repeat;
    background-size: contain;
    display: flex;
    justify-content: center;
    align-items: center;
  }

  h1, h2 {
    font-size: 2rem;
    color: #333;
  }

  footer .links {
    display: flex;
    justify-content: center;
    flex-wrap: wrap;
    gap: 12px;
  }

  footer .btn--remix {
    margin: 5px;
  }

  .linkButton {
    margin-bottom: 0.2cm;
  }
}
